import{bQ as e,aL as a,u as r,G as o}from"./chunks/framework.C1gZXFVa.js";const n="/assets/060101.DLYB8v6U.png",_=JSON.parse('{"title":"账务初始化链路","description":"账务起来之后如何就绪：在线能改账、批处理持续消化待入账流水；不做全站钱包预热。","frontmatter":{"title":"账务初始化链路","description":"账务起来之后如何就绪：在线能改账、批处理持续消化待入账流水；不做全站钱包预热。","head":[["meta",{"name":"keywords","content":"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX"}],["link",{"rel":"canonical","href":"https://tgex.net/pages/070506"}],["meta",{"property":"og:url","content":"https://tgex.net/pages/070506"}],["meta",{"property":"og:title","content":"账务初始化链路 · TGEX"}],["meta",{"property":"og:description","content":"账务起来之后如何就绪：在线能改账、批处理持续消化待入账流水；不做全站钱包预热。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://tgex.net/og.jpg"}],["meta",{"name":"twitter:title","content":"账务初始化链路 · TGEX"}],["meta",{"name":"twitter:description","content":"账务起来之后如何就绪：在线能改账、批处理持续消化待入账流水；不做全站钱包预热。"}],["meta",{"name":"twitter:image","content":"https://tgex.net/og.jpg"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"账务初始化链路\\",\\"description\\":\\"账务起来之后如何就绪：在线能改账、批处理持续消化待入账流水；不做全站钱包预热。\\",\\"keywords\\":\\"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX\\",\\"url\\":\\"https://tgex.net/pages/070506\\",\\"mainEntityOfPage\\":\\"https://tgex.net/pages/070506\\",\\"inLanguage\\":\\"zh-CN\\",\\"isPartOf\\":{\\"@type\\":\\"WebSite\\",\\"name\\":\\"TGEX\\",\\"url\\":\\"https://tgex.net/\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://tgex.net/logo.svg\\"}},\\"image\\":\\"https://tgex.net/og.jpg\\"}"]]},"headers":[],"relativePath":"pages/070506.md","filePath":"07.现货手册/05.核心流程/06.账务初始化链路.md"}'),i={name:"pages/070506.md"};function p(s,t,h,d,l,c){return a(),r("div",null,[...t[0]||(t[0]=[o('<div class="doc-eyebrow">现货手册 · 核心交易流程 / TGEX KNOWLEDGE BASE</div><h1 id="账务初始化链路" tabindex="-1">账务初始化链路 <a class="header-anchor" href="#账务初始化链路" aria-label="Permalink to &quot;账务初始化链路&quot;">​</a></h1><div class="doc-lead">账务起来之后不做「把全站用户余额装进内存」。在线侧能改账、能收资产消息；批处理侧持续把待入账流水消化掉。图上两支并行，是两条一起跑的能力。</div><p align="center"><img src="'+n+'" alt="账务初始化链路"></p><table tabindex="0"><thead><tr><th>一支</th><th>干什么</th></tr></thead><tbody><tr><td>在线账务</td><td>响应改账请求，消费资产相关消息</td></tr><tr><td>账务批处理</td><td>扫描待入账 / 异常流水，做补偿与检索同步</td></tr></tbody></table><p>下文按上图节点展开。平台现货下单热路径上的占用，多在撮合内存完成（见<a href="/pages/070802">用户币币账户缓存</a>）；本文讲的是<strong>账务工程自身</strong>如何就绪，以及充提、调账、异步流水等仍依赖它的部分。</p><h2 id="_1-配置与存储通道就绪" tabindex="-1">1. 配置与存储通道就绪 <a class="header-anchor" href="#_1-配置与存储通道就绪" aria-label="Permalink to &quot;1. 配置与存储通道就绪&quot;">​</a></h2><p>配置、数据库、缓存、检索、远程调用等先就绪。下游暂时不在线，一般不挡本服务起来。</p><h2 id="_2-在线账务-对外提供改账能力" tabindex="-1">2. 在线账务：对外提供改账能力 <a class="header-anchor" href="#_2-在线账务-对外提供改账能力" aria-label="Permalink to &quot;2. 在线账务：对外提供改账能力&quot;">​</a></h2><p>对外提供用户币币钱包、商户钱包、各类业务改账、管理向调账等能力。<br> 其它服务能调到这些能力，在线账务才算「门面在」。</p><h2 id="_3-在线账务-订阅资产相关消息" tabindex="-1">3. 在线账务：订阅资产相关消息 <a class="header-anchor" href="#_3-在线账务-订阅资产相关消息" aria-label="Permalink to &quot;3. 在线账务：订阅资产相关消息&quot;">​</a></h2><p>挂上资产相关消息与内部事件，例如：余额批量更新、提现或手续费结果、场外成交入账、外部划转结果等。</p><p>启动时只挂监听，<strong>不</strong>扫全站账户。有积压则起来后立刻消费；真正改账发生在「有请求或有消息」时，不在启动预热阶段。</p><h2 id="_4-在线账务-探活并保持在线" tabindex="-1">4. 在线账务：探活并保持在线 <a class="header-anchor" href="#_4-在线账务-探活并保持在线" aria-label="Permalink to &quot;4. 在线账务：探活并保持在线&quot;">​</a></h2><p>轻量查库确认库可读，进程保持运行。运行中还有充值对齐、超时关单一类定时事务，属于日常运转，不是「启动时一次性灌钱包」。</p><p>用户某币种还没有钱包时，往往在<strong>第一次动到该币</strong>时再建——同样是请求路径上的事，不是启动全量建账。</p><h2 id="_5-在线账务-按请求改账-不预热" tabindex="-1">5. 在线账务：按请求改账（不预热） <a class="header-anchor" href="#_5-在线账务-按请求改账-不预热" aria-label="Permalink to &quot;5. 在线账务：按请求改账（不预热）&quot;">​</a></h2><p>没有「启动完成 = 全站余额已在内存」这种状态。<br> 在线就绪的含义是：能响应改账、能消费消息；需要哪份余额，再按请求加载或创建。</p><h2 id="_6-账务批处理-启动后开始循环扫描" tabindex="-1">6. 账务批处理：启动后开始循环扫描 <a class="header-anchor" href="#_6-账务批处理-启动后开始循环扫描" aria-label="Permalink to &quot;6. 账务批处理：启动后开始循环扫描&quot;">​</a></h2><p>另一条能力线。起来后不久就开始一轮轮扫描，而不是等人手点一次。</p><h2 id="_7-账务批处理-消化待入账-·-补偿-·-检索同步" tabindex="-1">7. 账务批处理：消化待入账 · 补偿 · 检索同步 <a class="header-anchor" href="#_7-账务批处理-消化待入账-·-补偿-·-检索同步" aria-label="Permalink to &quot;7. 账务批处理：消化待入账 · 补偿 · 检索同步&quot;">​</a></h2><p>持续处理：待入账流水落地、异常再试、流水与资产快照进检索侧等。<br> 它不预加载全站余额，但保证「在线已经记下的待办」被消化。现货高峰若只开在线、不开批处理，容易出现：即时余额看起来变了，流水检索或异步链路却还滞后。</p><h2 id="就绪怎么理解" tabindex="-1">就绪怎么理解 <a class="header-anchor" href="#就绪怎么理解" aria-label="Permalink to &quot;就绪怎么理解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问法</th><th>答案</th></tr></thead><tbody><tr><td>能不能调改账？</td><td>在线门面起来后可以</td></tr><tr><td>资产消息会不会积在门口？</td><td>订阅挂上后可以消费</td></tr><tr><td>待入账会不会一直堆着？</td><td>要看批处理循环是否在跑</td></tr><tr><td>是不是所有用户余额都已预热？</td><td><strong>不是</strong>，本来就没有这一步</td></tr></tbody></table><h2 id="本文边界" tabindex="-1">本文边界 <a class="header-anchor" href="#本文边界" aria-label="Permalink to &quot;本文边界&quot;">​</a></h2><p>委托入口见<a href="/pages/070504">委托初始化链路</a>；撮合盘口恢复见<a href="/pages/070505">撮合初始化链路</a>；撮合侧可用/冻结权威见<a href="/pages/070802">用户币币账户缓存</a>；运行时充提如何对齐热缓存见<a href="/pages/070511">充提改账协同</a>；资金教学见<a href="/pages/0701">业务概述</a>。</p><p>同组：<a href="/pages/070504">委托初始化链路</a> · <a href="/pages/070505">撮合初始化链路</a> · <a href="/pages/070507">行情初始化链路</a> · <a href="/pages/070511">充提改账协同</a></p>',27)])])}const m=e(i,[["render",p]]);export{_ as __pageData,m as default};
